-- CounterNest POS v1.12.0 / Phase 32.0-32.9
-- Internal production cutover, controlled day close, acceptance, and go-live sign-off.

alter table public.cash_drawer_sessions add column if not exists business_date date;
alter table public.cash_drawer_sessions add column if not exists variance_reason text;
alter table public.cash_drawer_sessions add column if not exists closure_reference text;
alter table public.cash_drawer_sessions add column if not exists close_confirmed boolean not null default false;

update public.cash_drawer_sessions s
set business_date=(s.opened_at at time zone coalesce(sh.timezone,'UTC'))::date
from public.shops sh
where sh.id=s.shop_id and s.business_date is null;
alter table public.cash_drawer_sessions alter column business_date set not null;
create index if not exists cash_drawer_business_date_idx on public.cash_drawer_sessions(shop_id,business_date desc);
create unique index if not exists cash_drawer_closure_reference_idx on public.cash_drawer_sessions(closure_reference) where closure_reference is not null;

create table if not exists public.daily_cash_closure_events(
  id uuid primary key default gen_random_uuid(),
  event_number bigint generated by default as identity,
  shop_id uuid not null references public.shops(id) on delete cascade,
  session_id uuid not null unique references public.cash_drawer_sessions(id) on delete restrict,
  business_date date not null,
  expected_amount numeric(12,2) not null,
  counted_amount numeric(12,2) not null,
  variance numeric(12,2) not null,
  variance_reason text,
  closing_note text not null,
  transaction_count integer not null,
  transaction_total numeric(12,2) not null,
  closed_by uuid not null references auth.users(id) on delete restrict,
  closed_at timestamptz not null default now()
);
create index if not exists daily_cash_closure_shop_date_idx on public.daily_cash_closure_events(shop_id,business_date desc);
alter table public.daily_cash_closure_events enable row level security;
drop policy if exists daily_cash_closure_admin_select on public.daily_cash_closure_events;
create policy daily_cash_closure_admin_select on public.daily_cash_closure_events for select to authenticated using(shop_id=public.current_shop_id() and public.is_admin());

create table if not exists public.phase32_go_live_reviews(
  id uuid primary key default gen_random_uuid(),
  shop_id uuid not null references public.shops(id) on delete cascade,
  release_version text not null default '1.12.0',
  phase text not null default '32.9',
  status text not null check(status in('draft','approved')),
  checklist jsonb not null,
  notes text,
  reviewed_by uuid not null references auth.users(id) on delete restrict,
  reviewed_at timestamptz not null default now(),
  approved_at timestamptz,
  constraint phase32_approval_fields check((status='draft' and approved_at is null) or(status='approved' and approved_at is not null))
);
create index if not exists phase32_review_shop_date_idx on public.phase32_go_live_reviews(shop_id,reviewed_at desc);
alter table public.phase32_go_live_reviews enable row level security;
drop policy if exists phase32_review_admin_select on public.phase32_go_live_reviews;
create policy phase32_review_admin_select on public.phase32_go_live_reviews for select to authenticated using(shop_id=public.current_shop_id() and public.is_admin());

create table if not exists public.phase32_go_live_events(
  id uuid primary key default gen_random_uuid(),
  shop_id uuid not null references public.shops(id) on delete cascade,
  review_id uuid not null references public.phase32_go_live_reviews(id) on delete restrict,
  action text not null check(action in('draft_saved','production_approved')),
  details jsonb not null default '{}'::jsonb,
  performed_by uuid not null references auth.users(id) on delete restrict,
  created_at timestamptz not null default now()
);
create index if not exists phase32_event_shop_date_idx on public.phase32_go_live_events(shop_id,created_at desc);
alter table public.phase32_go_live_events enable row level security;
drop policy if exists phase32_event_admin_select on public.phase32_go_live_events;
create policy phase32_event_admin_select on public.phase32_go_live_events for select to authenticated using(shop_id=public.current_shop_id() and public.is_admin());

create or replace function public.current_business_date() returns date
language sql security definer stable set search_path=public as $$
  select (now() at time zone coalesce((select timezone from public.shops where id=public.current_shop_id()),'UTC'))::date
$$;

create or replace function public.open_cash_drawer(p_opening_amount numeric,p_note text default null) returns uuid
language plpgsql security definer set search_path=public as $$
declare v_shop uuid:=public.current_shop_id();v_session uuid;v_date date:=public.current_business_date();
begin
  if auth.uid() is null or not public.is_admin() then raise exception 'Management access required'; end if;
  if p_opening_amount is null or p_opening_amount<0 then raise exception 'Opening cash cannot be negative'; end if;
  if exists(select 1 from public.cash_drawer_sessions where shop_id=v_shop and status='open') then raise exception 'A Daily Cash record is already open'; end if;
  if exists(select 1 from public.cash_drawer_sessions where shop_id=v_shop and business_date=v_date) then raise exception 'A Daily Cash record already exists for today and cannot be reopened'; end if;
  insert into public.cash_drawer_sessions(shop_id,business_date,opening_amount,opening_note,opened_by)
  values(v_shop,v_date,round(p_opening_amount,2),nullif(trim(p_note),''),auth.uid()) returning id into v_session;
  insert into public.cash_drawer_transactions(shop_id,session_id,transaction_type,amount,reason,performed_by)
  values(v_shop,v_session,'opening_float',round(p_opening_amount,2),coalesce(nullif(trim(p_note),''),'Opening float'),auth.uid());
  return v_session;
end $$;

create or replace function public.close_daily_cash(
  p_counted_amount numeric,p_variance_reason text,p_closing_note text,p_confirmation boolean
) returns jsonb
language plpgsql security definer set search_path=public as $$
declare v_shop uuid:=public.current_shop_id();v_session public.cash_drawer_sessions%rowtype;v_expected numeric(12,2);v_variance numeric(12,2);v_count integer;v_event_number bigint;v_reference text;
begin
  if auth.uid() is null or not public.is_admin() then raise exception 'Management access required'; end if;
  if p_confirmation is not true then raise exception 'Management confirmation is required'; end if;
  if p_counted_amount is null or p_counted_amount<0 then raise exception 'Counted cash cannot be negative'; end if;
  if length(trim(coalesce(p_closing_note,'')))<5 then raise exception 'A closing note of at least 5 characters is required'; end if;
  select * into v_session from public.cash_drawer_sessions where shop_id=v_shop and status='open' for update;
  if v_session.id is null then raise exception 'No Daily Cash record is open'; end if;
  select round(coalesce(sum(amount),0),2),count(*) into v_expected,v_count from public.cash_drawer_transactions where session_id=v_session.id;
  v_variance:=round(p_counted_amount,2)-v_expected;
  if abs(v_variance)>=0.01 and length(trim(coalesce(p_variance_reason,'')))<5 then raise exception 'Explain the cash variance using at least 5 characters'; end if;
  insert into public.daily_cash_closure_events(shop_id,session_id,business_date,expected_amount,counted_amount,variance,variance_reason,closing_note,transaction_count,transaction_total,closed_by)
  values(v_shop,v_session.id,v_session.business_date,v_expected,round(p_counted_amount,2),v_variance,nullif(trim(p_variance_reason),''),trim(p_closing_note),v_count,v_expected,auth.uid()) returning event_number into v_event_number;
  v_reference:='DC-'||to_char(v_session.business_date,'YYYYMMDD')||'-'||lpad(v_event_number::text,6,'0');
  update public.cash_drawer_sessions set status='closed',counted_amount=round(p_counted_amount,2),expected_amount=v_expected,variance=v_variance,
    variance_reason=nullif(trim(p_variance_reason),''),closing_note=trim(p_closing_note),close_confirmed=true,closure_reference=v_reference,closed_by=auth.uid(),closed_at=now()
  where id=v_session.id;
  return jsonb_build_object('session_id',v_session.id,'business_date',v_session.business_date,'closure_reference',v_reference,'expected_amount',v_expected,'counted_amount',round(p_counted_amount,2),'variance',v_variance);
end $$;

create or replace function public.get_cash_drawer() returns jsonb
language plpgsql security definer stable set search_path=public as $$
declare v_shop uuid:=public.current_shop_id();v_session uuid;
begin
  if auth.uid() is null or not public.is_admin() then raise exception 'Management access required'; end if;
  select id into v_session from public.cash_drawer_sessions where shop_id=v_shop and status='open';
  return jsonb_build_object(
    'business_date',public.current_business_date(),
    'open_session',(select to_jsonb(x) from(select s.id,s.status,s.business_date,s.opening_amount,coalesce(sum(t.amount),0) expected_amount,s.counted_amount,s.variance,s.variance_reason,s.closure_reference,s.close_confirmed,s.opened_at,s.closed_at,s.opening_note,s.closing_note,op.display_name opened_by_name,null::text closed_by_name from public.cash_drawer_sessions s left join public.cash_drawer_transactions t on t.session_id=s.id left join public.staff_profiles op on op.user_id=s.opened_by and op.shop_id=s.shop_id where s.id=v_session group by s.id,op.display_name)x),
    'transactions',coalesce((select jsonb_agg(to_jsonb(x) order by x.created_at desc) from(select t.*,sp.display_name staff_name,sa.receipt_number from public.cash_drawer_transactions t left join public.staff_profiles sp on sp.user_id=t.performed_by and sp.shop_id=t.shop_id left join public.sales sa on sa.id=t.sale_id where t.session_id=v_session)x),'[]'::jsonb),
    'recent_sessions',coalesce((select jsonb_agg(to_jsonb(x) order by x.opened_at desc) from(select s.*,op.display_name opened_by_name,cp.display_name closed_by_name from public.cash_drawer_sessions s left join public.staff_profiles op on op.user_id=s.opened_by and op.shop_id=s.shop_id left join public.staff_profiles cp on cp.user_id=s.closed_by and cp.shop_id=s.shop_id where s.shop_id=v_shop and s.status='closed' order by s.business_date desc,s.opened_at desc limit 30)x),'[]'::jsonb)
  );
end $$;

create or replace function public.get_daily_cash_report(p_session_id uuid) returns jsonb
language plpgsql security definer stable set search_path=public as $$
declare v_shop uuid:=public.current_shop_id();v_session public.cash_drawer_sessions%rowtype;
begin
  if auth.uid() is null or not public.is_admin() then raise exception 'Administrator access required'; end if;
  select * into v_session from public.cash_drawer_sessions where id=p_session_id and shop_id=v_shop;
  if v_session.id is null then raise exception 'Daily Cash record not found'; end if;
  return jsonb_build_object(
    'session',jsonb_build_object('id',v_session.id,'status',v_session.status,'business_date',v_session.business_date,'closure_reference',v_session.closure_reference,'opened_at',v_session.opened_at,'closed_at',v_session.closed_at,'opening_note',v_session.opening_note,'closing_note',v_session.closing_note,'variance_reason',v_session.variance_reason,'close_confirmed',v_session.close_confirmed,'counted_amount',v_session.counted_amount,'variance',v_session.variance,'opened_by',(select display_name from public.staff_profiles where user_id=v_session.opened_by and shop_id=v_shop),'closed_by',(select display_name from public.staff_profiles where user_id=v_session.closed_by and shop_id=v_shop)),
    'summary',(select jsonb_build_object('opening_cash',coalesce(sum(amount) filter(where transaction_type='opening_float'),0),'cash_sales',coalesce(sum(amount) filter(where transaction_type='cash_sale'),0),'cash_refunds',abs(coalesce(sum(amount) filter(where transaction_type='cash_refund'),0)),'cash_in',coalesce(sum(amount) filter(where transaction_type='cash_in'),0),'cash_out',abs(coalesce(sum(amount) filter(where transaction_type='cash_out'),0)),'expected_cash',coalesce(sum(amount),0),'transaction_count',count(*)) from public.cash_drawer_transactions where session_id=v_session.id),
    'transactions',(select coalesce(jsonb_agg(to_jsonb(x) order by x.created_at),'[]'::jsonb) from(select t.id,t.created_at,t.transaction_type,t.amount,t.reason,coalesce(sp.display_name,'System') staff_name,s.receipt_number from public.cash_drawer_transactions t left join public.staff_profiles sp on sp.user_id=t.performed_by and sp.shop_id=t.shop_id left join public.sales s on s.id=t.sale_id where t.session_id=v_session.id order by t.created_at)x),
    'closure_event',(select to_jsonb(e) from public.daily_cash_closure_events e where e.session_id=v_session.id)
  );
end $$;

create or replace function public.save_phase32_go_live_review(p_checklist jsonb,p_notes text,p_approve boolean default false) returns jsonb
language plpgsql security definer set search_path=public as $$
declare v_shop uuid:=public.current_shop_id();v_id uuid;v_status text:=case when p_approve then 'approved' else 'draft' end;v_complete integer;v_required integer;
begin
  if auth.uid() is null or not public.is_admin() then raise exception 'Administrator access required'; end if;
  if jsonb_typeof(p_checklist)<>'array' then raise exception 'The Phase 32 checklist must be an array'; end if;
  select count(*),count(*) filter(where coalesce((item->>'complete')::boolean,false)) into v_required,v_complete from jsonb_array_elements(p_checklist) item where item->>'phase' in('32.0','32.1','32.2','32.3','32.4','32.5','32.6','32.7','32.8','32.9');
  if v_required<>10 then raise exception 'All Phase 32.0 through 32.9 checklist items are required'; end if;
  if p_approve and v_complete<>10 then raise exception 'Complete every Phase 32 checklist item before production approval'; end if;
  if p_approve and length(trim(coalesce(p_notes,'')))<10 then raise exception 'Production approval requires a management note of at least 10 characters'; end if;
  insert into public.phase32_go_live_reviews(shop_id,status,checklist,notes,reviewed_by,approved_at)
  values(v_shop,v_status,p_checklist,nullif(trim(p_notes),''),auth.uid(),case when p_approve then now() end) returning id into v_id;
  insert into public.phase32_go_live_events(shop_id,review_id,action,details,performed_by)
  values(v_shop,v_id,case when p_approve then 'production_approved' else 'draft_saved' end,jsonb_build_object('completed',v_complete,'required',v_required,'notes',nullif(trim(p_notes),'')),auth.uid());
  return jsonb_build_object('id',v_id,'status',v_status,'completed',v_complete,'required',v_required,'reviewed_at',now());
end $$;

create or replace function public.get_phase32_go_live_status() returns jsonb
language plpgsql security definer stable set search_path=public as $$
declare v_shop uuid:=public.current_shop_id();v_date date:=public.current_business_date();
begin
  if auth.uid() is null or not public.is_admin() then raise exception 'Administrator access required'; end if;
  return jsonb_build_object(
    'business_date',v_date,
    'server_checks',jsonb_build_array(
      jsonb_build_object('id','active_admin','label','Active administrator','status',case when exists(select 1 from public.staff_profiles where shop_id=v_shop and active and role='admin') then 'pass' else 'fail' end,'detail','At least one active administrator must remain available.'),
      jsonb_build_object('id','active_products','label','Production catalog','status',case when exists(select 1 from public.products where shop_id=v_shop and active) then 'pass' else 'fail' end,'detail','At least one active product is required.'),
      jsonb_build_object('id','recent_backup','label','Recent protected backup','status',case when exists(select 1 from public.backup_exports where shop_id=v_shop and requested_at>=now()-interval '30 days') then 'pass' else 'fail' end,'detail','Create and verify a backup within 30 days.'),
      jsonb_build_object('id','inventory_integrity','label','Inventory integrity','status',case when exists(select 1 from public.ingredients where shop_id=v_shop and current_quantity<0) then 'fail' else 'pass' end,'detail','Negative ingredient balances are not allowed.'),
      jsonb_build_object('id','stale_daily_cash','label','Daily Cash date control','status',case when exists(select 1 from public.cash_drawer_sessions where shop_id=v_shop and status='open' and business_date<v_date) then 'fail' else 'pass' end,'detail','No prior-date Daily Cash record may remain open.'),
      jsonb_build_object('id','open_recalls','label','Recall resolution','status',case when exists(select 1 from public.finished_product_recall_cases where shop_id=v_shop and status='open') then 'warning' else 'pass' end,'detail','Open recalls require management review.'),
      jsonb_build_object('id','day_close_exercise','label','Day-close exercise','status',case when exists(select 1 from public.daily_cash_closure_events where shop_id=v_shop) then 'pass' else 'warning' end,'detail','Complete and verify at least one controlled day close.'),
      jsonb_build_object('id','phase32_acceptance','label','Phase 32 acceptance','status',coalesce((select case status when 'failed' then 'fail' when 'passed' then 'pass' else 'warning' end from public.operational_acceptance_runs where shop_id=v_shop and release_version='1.12.0' order by run_at desc limit 1),'warning'),'detail','Run the Phase 32 operational acceptance checks.')
    ),
    'latest_review',(select to_jsonb(x) from(select r.id,r.status,r.checklist,r.notes,r.reviewed_at,r.approved_at,coalesce(sp.display_name,'Former administrator') reviewed_by_name from public.phase32_go_live_reviews r left join public.staff_profiles sp on sp.user_id=r.reviewed_by and sp.shop_id=r.shop_id where r.shop_id=v_shop order by r.reviewed_at desc limit 1)x),
    'history',(select coalesce(jsonb_agg(to_jsonb(x) order by x.reviewed_at desc),'[]'::jsonb) from(select r.id,r.status,r.notes,r.reviewed_at,r.approved_at,coalesce(sp.display_name,'Former administrator') reviewed_by_name from public.phase32_go_live_reviews r left join public.staff_profiles sp on sp.user_id=r.reviewed_by and sp.shop_id=r.shop_id where r.shop_id=v_shop order by r.reviewed_at desc limit 20)x)
  );
end $$;

create or replace function public.run_phase32_operational_acceptance(p_notes text default null) returns jsonb
language plpgsql security definer set search_path=public as $$
declare v_shop uuid:=public.current_shop_id();v_date date:=public.current_business_date();v_checks jsonb;v_status text;v_id uuid;
begin
  if auth.uid() is null or not public.is_admin() then raise exception 'Administrator access required'; end if;
  v_checks:=jsonb_build_array(
    jsonb_build_object('id','active_admin','label','At least one active administrator','required',true,'status',case when exists(select 1 from public.staff_profiles where shop_id=v_shop and active and role='admin') then 'pass' else 'fail' end,'detail','Active management account check'),
    jsonb_build_object('id','active_products','label','Active product catalog','required',true,'status',case when exists(select 1 from public.products where shop_id=v_shop and active) then 'pass' else 'fail' end,'detail','Production catalog check'),
    jsonb_build_object('id','recent_backup','label','Verified backup within 30 days','required',true,'status',case when exists(select 1 from public.backup_exports where shop_id=v_shop and requested_at>=now()-interval '30 days') then 'pass' else 'fail' end,'detail','Protected backup evidence'),
    jsonb_build_object('id','inventory_integrity','label','No negative ingredient balances','required',true,'status',case when exists(select 1 from public.ingredients where shop_id=v_shop and current_quantity<0) then 'fail' else 'pass' end,'detail','Ingredient ledger integrity'),
    jsonb_build_object('id','stale_daily_cash','label','No prior-date Daily Cash record remains open','required',true,'status',case when exists(select 1 from public.cash_drawer_sessions where shop_id=v_shop and status='open' and business_date<v_date) then 'fail' else 'pass' end,'detail','Business-date close control'),
    jsonb_build_object('id','day_close_exercise','label','Controlled day close has been exercised','required',true,'status',case when exists(select 1 from public.daily_cash_closure_events where shop_id=v_shop) then 'pass' else 'fail' end,'detail','Closure reference and immutable event evidence'),
    jsonb_build_object('id','open_recall_cases','label','Recall cases reviewed','required',false,'status',case when exists(select 1 from public.finished_product_recall_cases where shop_id=v_shop and status='open') then 'warning' else 'pass' end,'detail','Open recalls require management action'),
    jsonb_build_object('id','uncosted_products','label','Active products have unit cost','required',false,'status',case when exists(select 1 from public.products where shop_id=v_shop and active and coalesce(cost_price,0)=0) then 'warning' else 'pass' end,'detail','Profitability guidance requires costs')
  );
  v_status:=case when exists(select 1 from jsonb_array_elements(v_checks) c where c->>'status'='fail') then 'failed' when exists(select 1 from jsonb_array_elements(v_checks) c where c->>'status'='warning') then 'warning' else 'passed' end;
  insert into public.operational_acceptance_runs(shop_id,release_version,phase,status,checks,notes,run_by) values(v_shop,'1.12.0','32.0-32.9',v_status,v_checks,nullif(trim(p_notes),''),auth.uid()) returning id into v_id;
  return jsonb_build_object('id',v_id,'release_version','1.12.0','phase','32.0-32.9','status',v_status,'checks',v_checks,'notes',nullif(trim(p_notes),''),'run_at',now());
end $$;

create or replace function public.get_phase32_acceptance_history() returns jsonb
language plpgsql security definer stable set search_path=public as $$
declare v_shop uuid:=public.current_shop_id();
begin
  if auth.uid() is null or not public.is_admin() then raise exception 'Administrator access required'; end if;
  return(select coalesce(jsonb_agg(to_jsonb(x) order by x.run_at desc),'[]'::jsonb) from(select r.id,r.release_version,r.phase,r.status,r.checks,r.notes,r.run_at,coalesce(sp.display_name,'Former staff') run_by_name from public.operational_acceptance_runs r left join public.staff_profiles sp on sp.user_id=r.run_by and sp.shop_id=r.shop_id where r.shop_id=v_shop and r.release_version='1.12.0' order by r.run_at desc limit 25)x);
end $$;

-- Preserve the established business export and append Phase 32 evidence without
-- duplicating the earlier portable-export implementation.
alter function public.export_business_backup() rename to export_business_backup_phase31_base;
revoke all on function public.export_business_backup_phase31_base() from public;
revoke all on function public.export_business_backup_phase31_base() from authenticated;
create or replace function public.export_business_backup() returns jsonb
language plpgsql security definer set search_path=public as $$
declare v_shop uuid:=public.current_shop_id();v_base jsonb;v_export uuid;
begin
  if auth.uid() is null or not public.is_admin() then raise exception 'Administrator access required'; end if;
  v_base:=public.export_business_backup_phase31_base();
  v_export:=(v_base->>'export_id')::uuid;
  update public.backup_exports set schema_version='1.12.0' where id=v_export and shop_id=v_shop;
  return (v_base-'schema_version')||jsonb_build_object(
    'schema_version','1.12.0',
    'daily_cash_closure_events',(select coalesce(jsonb_agg(to_jsonb(t)),'[]'::jsonb) from public.daily_cash_closure_events t where shop_id=v_shop),
    'phase32_go_live_reviews',(select coalesce(jsonb_agg(to_jsonb(t)),'[]'::jsonb) from public.phase32_go_live_reviews t where shop_id=v_shop),
    'phase32_go_live_events',(select coalesce(jsonb_agg(to_jsonb(t)),'[]'::jsonb) from public.phase32_go_live_events t where shop_id=v_shop)
  );
end $$;

revoke all on function public.current_business_date() from public;
revoke all on function public.close_cash_drawer(numeric,text) from authenticated;
revoke all on function public.close_daily_cash(numeric,text,text,boolean) from public;
revoke all on function public.get_phase32_go_live_status() from public;
revoke all on function public.save_phase32_go_live_review(jsonb,text,boolean) from public;
revoke all on function public.run_phase32_operational_acceptance(text) from public;
revoke all on function public.get_phase32_acceptance_history() from public;
revoke all on function public.export_business_backup() from public;
grant execute on function public.current_business_date() to authenticated;
grant execute on function public.close_daily_cash(numeric,text,text,boolean) to authenticated;
grant execute on function public.get_phase32_go_live_status() to authenticated;
grant execute on function public.save_phase32_go_live_review(jsonb,text,boolean) to authenticated;
grant execute on function public.run_phase32_operational_acceptance(text) to authenticated;
grant execute on function public.get_phase32_acceptance_history() to authenticated;
grant execute on function public.export_business_backup() to authenticated;
